// Renders one research page from research/index.json (generated by scripts/build_index.py),
// chosen by the URL hash: project.html#<slug>
(function () {
  "use strict";

  function el(tag, attrs, children) {
    var node = document.createElement(tag);
    Object.keys(attrs || {}).forEach(function (k) {
      if (k === "text") node.textContent = attrs[k];
      else node.setAttribute(k, attrs[k]);
    });
    (children || []).forEach(function (c) { node.appendChild(c); });
    return node;
  }

  var root = document.getElementById("project");

  function render(entries) {
    var slug = decodeURIComponent(location.hash.slice(1));
    var p = entries.filter(function (e) { return e.slug === slug; })[0];
    if (!p) {
      document.title = "Research | Yashowardhan Rai";
      root.replaceChildren(
        el("a", { class: "back", href: "index.html#research", text: "← All research" }),
        el("h1", { text: "Project not found" }),
        el("p", { class: "empty", text: "This research page does not exist yet." })
      );
      return;
    }
    var meta = [p.guide, p.period].filter(Boolean).join(" · ");
    root.replaceChildren(
      el("a", { class: "back", href: "index.html#research", text: "← All research" }),
      el("h1", { text: p.title }),
      el("p", { class: "meta", text: meta }),
      el("p", { class: "lede-p", text: p.summary })
    );
    if (p.tags && p.tags.length) {
      root.appendChild(el("div", { class: "tags", style: "margin-top:0.5rem" }, p.tags.map(function (t) {
        return el("span", { class: "tag", text: t });
      })));
    }
    if (p.links && p.links.length) {
      root.appendChild(el("div", { class: "links" }, p.links.map(function (l) {
        var a = el("a", { class: "btn", href: l.url, text: l.label });
        if (window.Viewer && Viewer.canEmbed(l.url)) { a.setAttribute("data-embed", ""); a.setAttribute("data-title", l.label); }
        return a;
      })));
    }
    var body = el("div", { class: "prose" });
    body.innerHTML = marked.parse(p.body || "");
    root.appendChild(body);
    document.title = p.title + " | Yashowardhan Rai";
  }

  fetch("research/index.json", { cache: "no-cache" })
    .then(function (r) { if (!r.ok) throw new Error(r.status); return r.json(); })
    .catch(function () { return []; })
    .then(function (entries) {
      render(entries);
      window.addEventListener("hashchange", function () { render(entries); window.scrollTo(0, 0); });
    });
})();
